package in.tucor.api.buyer; import org.springframework.data.jpa.repository.*; import java.util.*; public interface BuyerOrderRepository extends JpaRepository<BuyerOrder,UUID>{List<BuyerOrder> findByBuyerIdOrderByCreatedAtDesc(UUID buyerId); Optional<BuyerOrder> findByBuyerIdAndPublicId(UUID buyerId,String publicId);@Lock(jakarta.persistence.LockModeType.PESSIMISTIC_WRITE) @Query("select o from BuyerOrder o where o.buyerId=:buyerId and o.publicId=:publicId") Optional<BuyerOrder> findByBuyerIdAndPublicIdForUpdate(UUID buyerId,String publicId);@Lock(jakarta.persistence.LockModeType.PESSIMISTIC_WRITE) @Query("select o from BuyerOrder o where o.publicId=:publicId") Optional<BuyerOrder> findByPublicIdForUpdate(String publicId);@Query("select o from BuyerOrder o join MarketListing l on l.id=o.listingId where l.sellerId=:sellerId order by o.createdAt desc") List<BuyerOrder> findForSeller(UUID sellerId);@Query("select o from BuyerOrder o join MarketListing l on l.id=o.listingId where l.sellerId=:sellerId and o.publicId=:publicId") Optional<BuyerOrder> findForSellerByPublicId(UUID sellerId,String publicId);}
